/** WhatsApp-style bubble corners — subtle radius, small tail on last bubble in group. */
const R = 8;
const R_SM = 3;
const TAIL = 2;

export function getLeadChatBubbleShape({ isMine, isFirstInGroup, isLastInGroup }) {
  if (isMine) {
    return {
      borderTopLeftRadius: `${R}px`,
      borderTopRightRadius: isFirstInGroup ? `${R}px` : `${R_SM}px`,
      borderBottomLeftRadius: `${R}px`,
      borderBottomRightRadius: isLastInGroup ? `${TAIL}px` : `${R_SM}px`,
    };
  }

  return {
    borderTopLeftRadius: isFirstInGroup ? `${R}px` : `${R_SM}px`,
    borderTopRightRadius: `${R}px`,
    borderBottomLeftRadius: isLastInGroup ? `${TAIL}px` : `${R_SM}px`,
    borderBottomRightRadius: `${R}px`,
  };
}
