import React, { useCallback, useEffect, useMemo, useRef } from 'react';
import { createReconnectingSocket } from '../../../../../shared/sockets';
import { LEAD_CHAT_CLIENT_EVENTS } from '../constants/leadChatApi';
import { parseLeadChatPayload } from './parseLeadChatPayload';
import {
  buildLeadChatSocketUrl,
  buildLeadChatStatusSocketUrl,
} from './buildLeadChatSocketUrls';

const LeadChatSocketContext = React.createContext(null);

export function useLeadChatSocketContext() {
  const ctx = React.useContext(LeadChatSocketContext);
  if (!ctx) {
    throw new Error('useLeadChatSocketContext must be used within LeadChatSocketProvider');
  }
  return ctx;
}

export function LeadChatSocketProvider({
  children,
  organisationId,
  botNumber,
  phoneNumber,
  agentName,
  onPayload,
}) {
  const chatSocketRef = useRef(null);
  const statusSocketRef = useRef(null);
  const onPayloadRef = useRef(onPayload);
  onPayloadRef.current = onPayload;

  const sendChatEvent = useCallback((event) => {
    chatSocketRef.current?.send(event);
  }, []);

  const sendMarkRead = useCallback(() => {
    if (!botNumber || !phoneNumber) return;
    sendChatEvent({
      type: LEAD_CHAT_CLIENT_EVENTS.MARK_READ,
      bot_number: botNumber,
      phone_number: phoneNumber,
    });
  }, [botNumber, phoneNumber, sendChatEvent]);

  const sendActiveUser = useCallback(() => {
    if (!botNumber || !phoneNumber || !agentName) return;
    sendChatEvent({
      type: LEAD_CHAT_CLIENT_EVENTS.ACTIVE_USER,
      bot_number: botNumber,
      phone_number: phoneNumber,
      agent_name: agentName,
    });
  }, [agentName, botNumber, phoneNumber, sendChatEvent]);

  const sendInactiveUser = useCallback(() => {
    if (!botNumber || !phoneNumber) return;
    sendChatEvent({
      type: LEAD_CHAT_CLIENT_EVENTS.INACTIVE_USER,
      bot_number: botNumber,
      phone_number: phoneNumber,
    });
  }, [botNumber, phoneNumber, sendChatEvent]);

  const sendWatchBot = useCallback(() => {
    if (!botNumber) return;
    sendChatEvent({
      type: LEAD_CHAT_CLIENT_EVENTS.WATCH_BOT,
      bot_number: botNumber,
    });
  }, [botNumber, sendChatEvent]);

  useEffect(() => {
    const url = buildLeadChatSocketUrl(botNumber, organisationId);
    if (!url) return undefined;

    const socket = createReconnectingSocket(url, {
      onOpen: () => {
        sendWatchBot();
        sendActiveUser();
      },
    });
    chatSocketRef.current = socket;

    const unsub = socket.on('message', (payload) => {
      const parsed = parseLeadChatPayload(payload);
      if (parsed) onPayloadRef.current?.(parsed);
    });

    return () => {
      unsub();
      sendInactiveUser();
      socket.disconnect();
      chatSocketRef.current = null;
    };
  }, [botNumber, organisationId, sendActiveUser, sendInactiveUser, sendWatchBot]);

  useEffect(() => {
    const url = buildLeadChatStatusSocketUrl(botNumber, phoneNumber);
    if (!url) return undefined;

    const socket = createReconnectingSocket(url);
    statusSocketRef.current = socket;

    const unsub = socket.on('message', (payload) => {
      const parsed = parseLeadChatPayload(payload);
      if (parsed) onPayloadRef.current?.(parsed);
    });

    return () => {
      unsub();
      socket.disconnect();
      statusSocketRef.current = null;
    };
  }, [botNumber, phoneNumber]);

  useEffect(() => {
    sendWatchBot();
    sendActiveUser();
    sendMarkRead();
  }, [sendActiveUser, sendMarkRead, sendWatchBot]);

  const value = useMemo(
    () => ({ sendMarkRead, sendActiveUser, sendInactiveUser }),
    [sendActiveUser, sendInactiveUser, sendMarkRead]
  );

  return (
    <LeadChatSocketContext.Provider value={value}>
      {children}
    </LeadChatSocketContext.Provider>
  );
}
