import React from 'react';
import {
  Box,
  Divider,
  Grid,
  TextField,
  Typography,
} from '@mui/material';
import SearchableDropdown from '../../../../components/FlowBuilder/Common/SearchableDropdown/SearchableDropdown.tsx';
import DateRangeFilter from '../../../../components/Shared/DateRangeFilter/DateRangeFilter.tsx';
import CommonTimePicker from '../../../../components/Shared/DateTimePicker/TimePicker.tsx';
import { Button } from '../../../../components/ui';
import { convertToReadableFormat } from '../../../../utils/helper.jsx';
import { RECORD_COPY } from '../constants/recordCopy';
import useDynamicFilters from '../hooks/useDynamicFilters';
import {
  getOperatorsForFieldType,
  getScopedSubStatusFilterOptions,
  toFilterOptions,
} from '../utils/dynamicFilterUtils';

export default function FiltersContent({
  open,
  formItems,
  tableId,
  workspaceId,
  appliedFilters,
  onApply,
  onClear,
  isCampaignOwner = true,
  styles,
}) {
  const {
    filtersArray,
    typeOfStatusList,
    statusList,
    assignedUsersList,
    loadingAssignedUsers,
    statusObj,
    setStatusObj,
    assigneeObj,
    setAssigneeObj,
    dateRange,
    setDateRange,
    updateFilter,
    handleApply,
    handleClear,
  } = useDynamicFilters({
    open,
    formItems,
    tableId,
    workspaceId,
    appliedFilters,
    isCampaignOwner,
  });

  const renderValueInput = (filter, index) => {
    const { field_type: fieldType, value, key_options: keyOptions = [] } = filter;

    switch (fieldType) {
      case 'BOOLEAN':
        return (
          <SearchableDropdown
            size="small"
            label="Value"
            options={[
              { label: 'True', value: true },
              { label: 'False', value: false },
            ]}
            value={
              typeof value === 'boolean'
                ? { label: value ? 'True' : 'False', value }
                : null
            }
            onChange={(option) => updateFilter(index, {
              value: typeof option?.value === 'boolean' ? option.value : null,
            })}
            labelKey="label"
            valueKey="value"
          />
        );

      case 'CHECKBOX':
        return (
          <SearchableDropdown
            size="small"
            label="Select Options"
            multiSelect
            options={toFilterOptions(keyOptions)}
            value={(Array.isArray(value) ? value : []).map((entry) => {
              const str = String(entry);
              return { label: convertToReadableFormat(str), value: str };
            })}
            onChange={(options) => updateFilter(index, {
              value: (options || []).map((option) => option.value),
            })}
            labelKey="label"
            valueKey="value"
          />
        );

      case 'RADIO':
      case 'DROPDOWN':
        if (filter?.statusOption === 'is_status') {
          return (
            <SearchableDropdown
              size="small"
              label="Value"
              options={typeOfStatusList[filter?.key_name] || []}
              value={
                typeOfStatusList[filter?.key_name]?.find(
                  (entry) => entry.status_id === filter?.status_id
                ) || null
              }
              onChange={(option) => updateFilter(index, {
                value: option?.status_name || '',
                status_id: option?.status_id || '',
                statusOption: filter?.statusOption || '',
              })}
              labelKey="status_name"
              valueKey="status_id"
            />
          );
        }

        if (filter?.statusOption === 'is_sub_status') {
          const scopedSubStatusOptions = getScopedSubStatusFilterOptions(
            typeOfStatusList,
            filter,
            filtersArray
          );

          return (
            <SearchableDropdown
              size="small"
              label="Value"
              options={scopedSubStatusOptions}
              value={
                scopedSubStatusOptions.find(
                  (entry) => entry.sub_status_id === filter?.sub_status_id
                ) || null
              }
              onChange={(option) => updateFilter(index, {
                value: option?.status_name || '',
                status_id: option?.status_id || '',
                statusOption: filter?.statusOption || '',
                sub_status_id: option?.sub_status_id || '',
              })}
              labelKey="name"
              valueKey="sub_status_id"
            />
          );
        }

        return (
          <SearchableDropdown
            size="small"
            label="Value"
            options={toFilterOptions(keyOptions)}
            value={
              typeof value === 'string' && value
                ? { label: convertToReadableFormat(value), value }
                : null
            }
            onChange={(option) => updateFilter(index, { value: option?.value || '' })}
            labelKey="label"
            valueKey="value"
          />
        );

      case 'DATE':
        if (filter.operator === 'range') {
          return (
            <DateRangeFilter
              buttonLabel="Select Date"
              startDate={value?.start_date ?? null}
              endDate={value?.end_date ?? null}
              onApply={(range) => {
                updateFilter(index, {
                  value: {
                    start_date: range?.startDate ?? null,
                    end_date: range?.endDate ?? null,
                  },
                });
              }}
            />
          );
        }

        return (
          <TextField
            fullWidth
            size="small"
            type="date"
            label="Value"
            InputLabelProps={{ shrink: true }}
            value={value || ''}
            onChange={(event) => updateFilter(index, { value: event.target.value })}
          />
        );

      case 'TIME':
        return (
          <CommonTimePicker
            label="Value"
            value={value || null}
            onChange={(time) => {
              if (time instanceof Date && !Number.isNaN(time.getTime())) {
                const hh = String(time.getHours()).padStart(2, '0');
                const mm = String(time.getMinutes()).padStart(2, '0');
                updateFilter(index, { value: `${hh}:${mm}` });
              } else {
                updateFilter(index, { value: time });
              }
            }}
            size="small"
            fullWidth
          />
        );

      case 'STRING':
      case 'EMAIL':
      case 'INT':
      case 'FLOAT':
      case 'PHONE':
      case 'PASSWORD':
      case 'TEXT':
      case 'TEXTAREA':
        if (filter.operator === 'range') {
          return (
            <Grid container spacing={1}>
              <Grid item xs={6}>
                <TextField
                  fullWidth
                  size="small"
                  type="number"
                  label="start_number"
                  value={value?.start_number ?? ''}
                  onChange={(event) => updateFilter(index, {
                    value: {
                      start_number: event.target.value,
                      end_number: value?.end_number ?? '',
                    },
                  })}
                />
              </Grid>
              <Grid item xs={6}>
                <TextField
                  fullWidth
                  size="small"
                  type="number"
                  label="end_number"
                  value={value?.end_number ?? ''}
                  onChange={(event) => updateFilter(index, {
                    value: {
                      start_number: value?.start_number ?? '',
                      end_number: event.target.value,
                    },
                  })}
                />
              </Grid>
            </Grid>
          );
        }

        return (
          <TextField
            fullWidth
            size="small"
            type={
              fieldType === 'EMAIL'
                ? 'email'
                : fieldType === 'FLOAT' || fieldType === 'INT'
                  ? 'number'
                  : fieldType === 'PASSWORD'
                    ? 'password'
                    : 'text'
            }
            label="Value"
            value={value ?? ''}
            onChange={(event) => updateFilter(index, { value: event.target.value })}
            multiline={fieldType === 'TEXT' || fieldType === 'TEXTAREA'}
            minRows={fieldType === 'TEXT' || fieldType === 'TEXTAREA' ? 2 : undefined}
          />
        );

      default:
        return (
          <TextField
            fullWidth
            size="small"
            label="Value"
            value={value ?? ''}
            onChange={(event) => updateFilter(index, { value: event.target.value })}
          />
        );
    }
  };

  const renderDynamicField = (filter, index) => {
    const operators = getOperatorsForFieldType(filter.field_type);
    const showValue = !['is_empty', 'is_not_empty'].includes(filter.operator);
    const isRangeOperator = filter.operator === 'range';
    const hideOperator = filter.field_type === 'DATE';
    const displayLabel =
      convertToReadableFormat(filter.alias_name) || convertToReadableFormat(filter.key_name);

    return (
      <Grid container spacing={1}>
        <Grid item xs={3}>
          <Typography variant="subtitle2" sx={{ fontWeight: 500 }}>
            {displayLabel}
          </Typography>
        </Grid>
        {!hideOperator ? (
          <Grid item xs={isRangeOperator ? 3 : 5}>
            <SearchableDropdown
              size="small"
              label="Filter Type"
              options={operators}
              value={operators.find((option) => option.value === filter.operator) || null}
              onChange={(option) => updateFilter(index, { operator: option?.value || 'equals' })}
              labelKey="label"
              valueKey="value"
            />
          </Grid>
        ) : null}
        {showValue ? (
          <Grid item xs={isRangeOperator ? 6 : 4}>
            {renderValueInput(filter, index)}
          </Grid>
        ) : null}
      </Grid>
    );
  };

  return (
    <Box sx={styles?.recordsFiltersContent}>
      <Box sx={styles?.recordsFiltersHeaderRow}>
        <Typography sx={styles?.recordsFiltersTitle}>{RECORD_COPY.filters}</Typography>
        <Box sx={styles?.recordsFiltersQuickFilters}>
          <DateRangeFilter
            onApply={setDateRange}
            buttonLabel="Created At"
            startDate={dateRange.startDate}
            endDate={dateRange.endDate}
          />
        </Box>
      </Box>

      <Box sx={styles?.recordsFiltersLeadFilters}>
        <SearchableDropdown
          size="small"
          label="Status"
          options={statusList}
          value={statusObj}
          onChange={setStatusObj}
          labelKey="status_name"
          valueKey="status_id"
        />
        {isCampaignOwner ? (
          <SearchableDropdown
            size="small"
            label="Assigned to"
            options={assignedUsersList}
            value={assigneeObj}
            onChange={setAssigneeObj}
            labelKey="label"
            valueKey="id"
            loading={loadingAssignedUsers}
          />
        ) : null}
      </Box>

      <Divider />

      <Box sx={styles?.recordsFiltersFields}>
        {filtersArray.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            No filterable fields available
          </Typography>
        ) : (
          filtersArray.map((filter, index) => (
            <Box key={`${filter.key_name}-${index}`} sx={{ mb: 2 }}>
              {renderDynamicField(filter, index)}
            </Box>
          ))
        )}
      </Box>

      <Box sx={styles?.recordsFiltersFooter}>
        <Button
          variant="outline"
          size="sm"
          onClick={() => onClear(handleClear())}
        >
          Clear all
        </Button>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button variant="primary" size="sm" onClick={() => onApply(handleApply())}>
            Apply filters
          </Button>
        </Box>
      </Box>
    </Box>
  );
}
