const INVALID_NAME_PATTERN = /^(null|undefined|\?+|n\/?a|-|—|none|unknown|anonymous)$/i;
const LEAD_ID_PATTERN = /^[A-Za-z0-9]+[-_][A-Za-z0-9]+$/;

function toTrimmedString(value) {
  if (value == null) return '';
  return String(value).trim();
}

function looksLikeLeadId(value, leadId) {
  const text = toTrimmedString(value);
  if (!text) return false;
  if (leadId && text === String(leadId).trim()) return true;
  return LEAD_ID_PATTERN.test(text);
}

export function formatLeadChatPhone(value) {
  const digits = `${value ?? ''}`.replace(/\D/g, '');
  return digits || '';
}

export function getConversationPhone(user) {
  return formatLeadChatPhone(
    user?.phoneNumber
    || user?.phone_number
    || user?.phone
    || user?.mobile
    || ''
  );
}

export function getConversationProfileName(user) {
  const leadId = user?.leadId || user?.lead_id;
  const candidates = [
    user?.whatsapp_name,
    user?.whatsappName,
    user?.profileName,
    user?.name,
    user?.user_name,
    user?.customer_name,
  ];

  for (const candidate of candidates) {
    const value = toTrimmedString(candidate);
    if (!value || INVALID_NAME_PATTERN.test(value) || looksLikeLeadId(value, leadId)) {
      continue;
    }
    return value;
  }

  return '';
}

export function getConversationDisplayName(user, fallback = 'Customer') {
  return getConversationProfileName(user) || getConversationPhone(user) || fallback;
}

export function getConversationAvatarInitial(user) {
  const name = getConversationProfileName(user);
  if (name) return name.charAt(0).toUpperCase();

  const phone = getConversationPhone(user);
  if (phone) return phone.slice(-1);

  return '?';
}

export function formatLastSeenLabel(user) {
  const lastActive = user?.last_active_date || user?.lastActive;
  if (!lastActive) return '';
  try {
    const date = new Date(lastActive);
    if (Number.isNaN(date.getTime())) return '';
    return `Last active ${date.toLocaleString()}`;
  } catch {
    return '';
  }
}
